import{c as a,Q as t,j as s,m as r}from"./chunks/framework.DVSyX6JR.js";const b=JSON.parse('{"title":"Web flasher","description":"","frontmatter":{},"headers":[],"relativePath":"docs/flasher.md","filePath":"docs/flasher.md"}'),i={name:"docs/flasher.md"};function o(d,e,n,l,h,c){return t(),s("div",null,[...e[0]||(e[0]=[r(`<h1 id="web-flasher" tabindex="-1">Web flasher <a class="header-anchor" href="#web-flasher" aria-label="Permalink to &quot;Web flasher&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>MeshCoreNG publishes a GitHub Pages web flasher at:</p><ul><li><a href="/MeshCoreNG/flasher/">MeshCoreNG web flasher</a></li><li><a href="https://github.com/MichTronics/MeshCoreNG/releases" target="_blank" rel="noreferrer">GitHub Releases</a></li></ul><p>The flasher is a browser frontend for release firmware assets. It does not build firmware in the browser. It lists known board environments from <code>website/public/flasher/boards.json</code>, finds matching release files, and either flashes them directly or offers the correct download.</p><h2 id="browser-support" tabindex="-1">Browser support <a class="header-anchor" href="#browser-support" aria-label="Permalink to &quot;Browser support&quot;">​</a></h2><p>Use Chrome or Edge on a desktop operating system. Web Serial is required for direct flashing and console access.</p><p>Linux users may need permission for the serial device, usually by adding the user to the <code>dialout</code> group and reconnecting the USB cable.</p><h2 id="firmware-asset-types" tabindex="-1">Firmware asset types <a class="header-anchor" href="#firmware-asset-types" aria-label="Permalink to &quot;Firmware asset types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Device family</th><th>Release asset</th><th>Flasher behavior</th></tr></thead><tbody><tr><td>ESP32</td><td>merged <code>.bin</code></td><td>Direct Web Serial flashing.</td></tr><tr><td>nRF52</td><td>serial DFU <code>.zip</code></td><td>Serial DFU flashing when supported by the bootloader and asset.</td></tr><tr><td>RP2040</td><td><code>.uf2</code> or release download</td><td>Download-only unless a future browser flow is added.</td></tr><tr><td>STM32/Wio-E5</td><td><code>.bin</code>, <code>.hex</code> or release download</td><td>Download-only; use the normal vendor or DFU workflow.</td></tr><tr><td>Other download targets</td><td>release asset</td><td>Download-only with board-specific instructions.</td></tr></tbody></table><p><code>Download</code> in <code>boards.json</code> means the firmware is made available through the flasher page, but the board cannot be flashed through the same Web Serial flow.</p><h2 id="release-asset-naming" tabindex="-1">Release asset naming <a class="header-anchor" href="#release-asset-naming" aria-label="Permalink to &quot;Release asset naming&quot;">​</a></h2><p>The flasher matches assets by PlatformIO environment name:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;env&gt;-&lt;version&gt;-&lt;commit&gt;-merged.bin</span></span>
<span class="line"><span>&lt;env&gt;-&lt;version&gt;-&lt;commit&gt;.zip</span></span>
<span class="line"><span>&lt;env&gt;-&lt;version&gt;-&lt;commit&gt;.uf2</span></span></code></pre></div><p>The exact version and commit parts can change, but the environment name must match the <code>env</code> field in <code>boards.json</code>.</p><h2 id="release-tag-build-patterns" tabindex="-1">Release tag build patterns <a class="header-anchor" href="#release-tag-build-patterns" aria-label="Permalink to &quot;Release tag build patterns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tag pattern</th><th>Builds</th></tr></thead><tbody><tr><td><code>repeater-*</code></td><td>All <code>_repeater</code> variants.</td></tr><tr><td><code>companion-*</code></td><td>All <code>_companion_radio_ble</code> and <code>_companion_radio_usb</code> variants.</td></tr><tr><td><code>room-server-*</code></td><td>All <code>_room_server</code> variants.</td></tr><tr><td><code>bridge-tcp-*</code></td><td>All <code>_repeater_bridge_tcp</code> variants.</td></tr><tr><td><code>bridge-rs232-*</code></td><td>All <code>_repeater_bridge_rs232</code> variants.</td></tr><tr><td><code>bridge-ble-*</code></td><td>All <code>_repeater_bridge_ble</code> variants.</td></tr><tr><td><code>bridge-tcp-ble-*</code></td><td>All <code>_repeater_bridge_tcp_ble</code> variants.</td></tr></tbody></table><h2 id="adding-a-board" tabindex="-1">Adding a board <a class="header-anchor" href="#adding-a-board" aria-label="Permalink to &quot;Adding a board&quot;">​</a></h2><p>Add a new entry to <code>website/public/flasher/boards.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Board_env_name_repeater&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Board Name Repeater&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;chipFamily&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ESP32&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;description&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MeshCoreNG Repeater firmware for Board Name.&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Use <code>ESP32</code>, <code>nRF52</code>, or <code>Download</code> for the current web flasher paths. Keep the <code>env</code> exactly the same as the PlatformIO build environment and release asset prefix.</p><h2 id="wio-tracker-l1-notes" tabindex="-1">Wio Tracker L1 notes <a class="header-anchor" href="#wio-tracker-l1-notes" aria-label="Permalink to &quot;Wio Tracker L1 notes&quot;">​</a></h2><p>Wio Tracker L1 and Wio Tracker L1 E-Ink/L1 Pro firmware entries are included so companion, repeater and room-server variants can be found from the flasher page when release assets exist.</p><p>These boards are nRF52-based. If the bootloader supports serial DFU and the release provides a <code>.zip</code>, the web flasher can use that path. If the device is in a vendor DFU mode or needs a bootloader update first, download the asset and use the board-specific DFU workflow.</p><h2 id="github-pages-publishing" tabindex="-1">GitHub Pages publishing <a class="header-anchor" href="#github-pages-publishing" aria-label="Permalink to &quot;GitHub Pages publishing&quot;">​</a></h2><p>The Pages workflow mirrors release assets into <code>/flasher/firmware/</code>. This avoids browser CORS problems that occur when trying to fetch GitHub Release asset bytes directly.</p><p>When a release is published, the website should be rebuilt so the flasher uses the exact firmware files from that release. Manual Pages runs use the latest published release.</p>`,27)])])}const u=a(i,[["render",o]]);export{b as __pageData,u as default};
